// customers-pricing · кейсы cp-01, cp-02, cp-03 п.6, cp-05, cp-06, cp-12 (.qa/tests/customers-pricing/) — только чтение.
// Раскладка карточки по Figma 71:644 (#ba86d972, עבר QA 2026-10-05): детали слева, «הזמנות אחרונות» справа, плитки
// справа налево «הזמנה אחרונה · יתרה פתוחה · סה"כ רכישות · מס' הזמנות»; телефон — имя в 1 строку, без гориз. скролла.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const ACTIONS = 'פעולות';
const TEST_CARD = '/customers/a30f4767-3f86-4a49-a441-ecfd2faad6d0'; // клиент «test» (buyer, тел. 0531231235)
const rowOf = (page: Page, name: string) =>
  page.getByRole('button').filter({ hasText: name }).filter({ has: page.getByRole('button', { name: ACTIONS }) }).first();

async function openList(page: Page) {
  await page.goto('/customers');
  await expect(page.getByRole('heading', { level: 1, name: 'לקוחות' })).toBeVisible();
  await expect(page.getByText(/^מציג \d+–\d+ מתוך \d+ תוצאות$/)).toBeVisible({ timeout: 20_000 });
}

async function openCard(page: Page, name: string) {
  await openList(page);
  await page.getByPlaceholder('חיפוש לקוח לפי שם עסק או איש קשר').fill(name); // список разбит на страницы по 8
  await rowOf(page, name).getByText(name, { exact: true }).first().click();
  await expect(page).toHaveURL(/\/customers\/[0-9a-f-]{36}$/);
  await expect(page.getByRole('heading', { level: 1, name })).toBeVisible({ timeout: 20_000 });
}

const tile = (page: Page, label: string) =>
  page.getByRole('main').getByText(label, { exact: true }).locator('xpath=following-sibling::*[1]');

test.describe('customers — רשימה וכרטיס לקוח (מפיץ)', () => {
  test('עמוד לקוחות נטען בלי 400 ובלי approval_status #6a72fb85 @desktop @prod-safe', async ({ page }) => {
    const errors: string[] = [];
    page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
    const resp = page.waitForResponse((r) => /\/rest\/v1\/customers\?/.test(r.url()) && r.request().method() === 'GET');
    await openList(page);
    const r = await resp;
    expect(r.status()).toBe(200);
    expect(r.url()).not.toContain('approval_status');
    await expect(page.getByText('אירעה שגיאה בטעינת הלקוחות')).toHaveCount(0);
    expect(errors.filter((e) => /400|approval_status/.test(e))).toEqual([]);
  });

  test('שגיאה זמנית: alert ו«נסה שוב» טוען את הרשימה בלי רענון #6a72fb85 @desktop @prod-safe', async ({ page }) => {
    let fail = true;
    await page.route(/\/rest\/v1\/customers\?select=/, (route) =>
      fail ? route.fulfill({ status: 400, contentType: 'application/json', body: '{"message":"qa"}' }) : route.continue(),
    );
    await page.goto('/customers');
    const alert = page.getByRole('alert').filter({ hasText: 'אירעה שגיאה בטעינת הלקוחות. נסה שוב.' });
    await expect(alert).toBeVisible({ timeout: 20_000 });
    fail = false;
    await page.evaluate(() => ((window as any).__qaNoReload = true));
    await alert.getByRole('button', { name: 'נסה שוב' }).click();
    await expect(page.getByText(/^מציג \d+–\d+ מתוך \d+ תוצאות$/)).toBeVisible({ timeout: 20_000 });
    await expect(alert).toHaveCount(0);
    expect(await page.evaluate(() => (window as any).__qaNoReload)).toBe(true);
  });

  test('«קישור הצטרפות» רק ללקוח שלא השלים הצטרפות #6a8f0847 #5a2dbd @desktop @prod-safe', async ({ page }) => {
    // статусы и пункт «קישור הצטרפות» появляются после ответа customer_invites (до него — скелет, #08cb68 / customer-status-loading.spec.ts)
    const invites = page.waitForResponse((r) => /\/rest\/v1\/customer_invites\?/.test(r.url()) && r.request().method() === 'GET' && r.ok());
    await openList(page);
    await invites;
    const active = page.getByRole('button').filter({ hasText: 'פעיל' }).filter({ hasNotText: 'ממתין להזמנה' })
      .filter({ has: page.getByRole('button', { name: ACTIONS }) }).first();
    await active.getByRole('button', { name: ACTIONS }).click();
    await expect(page.getByRole('menuitem', { name: 'כרטיס לקוח' })).toBeVisible();
    await expect(page.getByRole('menuitem', { name: 'השבתת לקוח' })).toBeVisible();
    await expect(page.getByRole('menuitem', { name: 'קישור הצטרפות' })).toHaveCount(0);
    await page.keyboard.press('Escape');

    // не присоединился: «ממתין להזמנה» (ссылка есть) или «ללא כניסה לקטלוג» (ссылки нет, #5a2dbd)
    const pending = page.getByRole('button').filter({ hasText: /ממתין להזמנה|ללא כניסה לקטלוג/ })
      .filter({ has: page.getByRole('button', { name: ACTIONS }) }).first();
    test.skip(!(await pending.count()), 'нет клиента «ממתין להזמנה» / «ללא כניסה לקטלוג»');
    await pending.getByRole('button', { name: ACTIONS }).click();
    await expect(page.getByRole('menuitem', { name: 'קישור הצטרפות' })).toBeVisible();
    await page.keyboard.press('Escape');
  });

  test('שם לקוח ארוך נחתך ב-ellipsis, בלי גלילה אופקית #6a70a5da @desktop @prod-safe', async ({ page }) => {
    await openList(page);
    const names = page.getByRole('main').getByRole('button').filter({ has: page.getByRole('button', { name: ACTIONS }) });
    const count = await names.count();
    for (let i = 0; i < count; i++) {
      const res = await names.nth(i).evaluate((row) => {
        const rr = row.getBoundingClientRect();
        return [...row.querySelectorAll('*')].filter((e) => !e.children.length).map((e) => {
          const b = e.getBoundingClientRect();
          const cs = getComputedStyle(e);
          const clipped = e.scrollWidth <= e.clientWidth + 1 || (cs.overflow === 'hidden' && cs.textOverflow === 'ellipsis');
          return b.left >= rr.left - 1 && b.right <= rr.right + 1 && clipped;
        }).every(Boolean);
      });
      expect(res).toBe(true);
    }
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  });

  test('כרטיס לקוח: פרטים, טבלה, מונה = «מציג», סינון תשלום/משלוח #6a38cf5d #6a677c6b @desktop @prod-safe', async ({ page }) => {
    await openCard(page, "פיצוציה בע'ם");
    for (const h of ['פרטי קשר', 'כתובת אספקה', 'נציג מכירות', 'הזמנות אחרונות'])
      await expect(page.getByRole('heading', { level: 3, name: h })).toBeVisible();
    const rows = page.getByRole('button', { name: /^הזמנה #\d+/ });
    const shown = page.getByText(/^מציג \d+ מתוך \d+ הזמנות/);
    await expect(shown).toBeVisible();
    const total = Number((await shown.innerText()).match(/מתוך (\d+)/)![1]);
    if (!/נדחתה/.test(await shown.innerText())) await expect(tile(page, "מס' הזמנות")).toHaveText(String(total));
    await expect(rows).toHaveCount(total);

    await page.getByRole('combobox', { name: 'סינון לפי סטטוס תשלום' }).selectOption({ label: 'שולם' });
    const paid = await rows.count();
    expect(paid).toBeLessThan(total);
    for (let i = 0; i < paid; i++) await expect(rows.nth(i)).toContainText(/(?<!לא )שולם(?! חלקית)/);
    await expect(shown).toHaveText(new RegExp(`^מציג ${paid} מתוך ${total} הזמנות`));

    await page.getByRole('combobox', { name: 'סינון לפי סטטוס משלוח' }).selectOption({ label: 'סופקה' });
    const both = await rows.count();
    expect(both).toBeLessThanOrEqual(paid);
    for (let i = 0; i < both; i++) await expect(rows.nth(i)).toContainText(/(?<!טרם )סופקה\s*$/);

    await page.getByRole('combobox', { name: 'סינון לפי סטטוס תשלום' }).selectOption({ label: 'שולם חלקית' });
    await page.getByRole('combobox', { name: 'סינון לפי סטטוס משלוח' }).selectOption({ label: 'במשלוח' });
    if ((await rows.count()) === 0) await expect(page.getByText('אין הזמנות התואמות לסינון.')).toBeVisible();
  });

  test('הזמנה שנדחתה: מונה N−1 וההחרגה מסומנת במפורש #6a677c6b @desktop @prod-safe', async ({ page }) => {
    // «test» по id: в базе есть другие клиенты с именем «test»
    await page.goto(TEST_CARD);
    await expect(page.getByRole('heading', { level: 1, name: 'test' })).toBeVisible({ timeout: 20_000 });
    const shown = page.getByText(/^מציג \d+ מתוך \d+ הזמנות/);
    await expect(shown).toBeVisible();
    const rejected = await page.getByRole('button', { name: /^הזמנה #\d+ נדחתה/ }).count();
    test.skip(rejected === 0, 'у клиента «test» нет отклонённых заказов');
    const total = Number((await shown.innerText()).match(/מתוך (\d+)/)![1]);
    await expect(tile(page, "מס' הזמנות")).toHaveText(String(total - rejected));
    // ед. ч. при одной отклонённой, мн. ч. («N מהן נדחו ואינן נספרות») при нескольких
    await expect(shown).toContainText(/(נדחתה ואינה נספרת|נדחו ואינן נספרות) במס' ההזמנות/);
  });

  test('RTL בכרטיס לקוח: חץ «חזרה ללקוחות» מימין, אריחים מיושרים לימין #6a70a1e1 @desktop @prod-safe', async ({ page }) => {
    // «test» по id: в базе есть другие клиенты с именем «test»
    await page.goto(TEST_CARD);
    await expect(page.getByRole('heading', { level: 1, name: 'test' })).toBeVisible({ timeout: 20_000 });
    const back = page.getByRole('button', { name: 'חזרה ללקוחות' });
    const pos = await back.evaluate((b) => {
      const svg = b.querySelector('svg')!.getBoundingClientRect();
      // меряем сам текстовый узел (текст может лежать прямо в button, рядом с svg)
      const walker = document.createTreeWalker(b, NodeFilter.SHOW_TEXT);
      let txt: Node | null = null;
      while (walker.nextNode()) if (walker.currentNode.textContent?.includes('חזרה')) { txt = walker.currentNode; break; }
      const range = document.createRange();
      range.selectNodeContents(txt ?? b);
      const t = range.getBoundingClientRect();
      return { svgLeft: svg.left, textRight: t.right };
    });
    expect(pos.svgLeft).toBeGreaterThanOrEqual(pos.textRight - 1);
    for (const label of ["מס' הזמנות", 'סה"כ רכישות', 'יתרה פתוחה', 'הזמנה אחרונה']) {
      const labelEl = page.getByRole('main').getByText(label, { exact: true });
      const s = await labelEl.evaluate((e) => {
        const cs = getComputedStyle(e);
        return { dir: cs.direction, align: cs.textAlign };
      });
      expect(s.dir).toBe('rtl');
      expect(['start', 'right']).toContain(s.align);
      // значение (число / ₪ / дата) может быть dir=ltr — проверяем фактическое выравнивание вправо под подписью
      // правый край самого текста (Range), а не блока — блок может быть на всю ширину
      const textRight = (e: Element) => { const r = document.createRange(); r.selectNodeContents(e); return r.getBoundingClientRect().right; };
      const lr = await labelEl.evaluate(textRight);
      const vr = await tile(page, label).evaluate(textRight);
      expect(Math.abs(vr - lr)).toBeLessThanOrEqual(4);
    }
  });

  // ---- #ba86d972 (2026-10-05, עבר QA): карточка клиента как Figma 71:644 ----
  const TILES = ['הזמנה אחרונה', 'יתרה פתוחה', 'סה"כ רכישות', "מס' הזמנות"]; // справа налево

  test('כרטיס לקוח 1440 לפי Figma 71:644: פרטים משמאל, «הזמנות אחרונות» מימין, אריחים מימין לשמאל #ba86d972 #6a6755e0 @desktop @prod-safe', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(TEST_CARD);
    await expect(page.getByRole('heading', { level: 1, name: 'test' })).toBeVisible({ timeout: 20_000 });
    const orders = (await page.getByRole('heading', { level: 3, name: 'הזמנות אחרונות' }).boundingBox())!;
    for (const h of ['פרטי קשר', 'כתובת אספקה', 'נציג מכירות']) {
      const b = (await page.getByRole('heading', { level: 3, name: h }).boundingBox())!;
      expect(b.x + b.width, `«${h}» — в левой колонке, левее «הזמנות אחרונות»`).toBeLessThan(orders.x);
    }
    // плитки в одну строку, порядок справа налево — как в Figma
    const boxes = [];
    for (const t of TILES) boxes.push((await page.getByRole('main').getByText(t, { exact: true }).locator('..').boundingBox())!);
    for (let i = 1; i < boxes.length; i++) {
      expect(Math.abs(boxes[i].y - boxes[0].y), `«${TILES[i]}» в той же строке`).toBeLessThanOrEqual(2);
      expect(boxes[i].x + boxes[i].width, `«${TILES[i]}» левее «${TILES[i - 1]}»`).toBeLessThanOrEqual(boxes[i - 1].x + 1);
    }
  });

  for (const w of [390, 360, 320]) {
    test(`כרטיס לקוח בטלפון ${w}px: שם בשורה אחת, הכפתורים עוברים שורה, בלי גלילה אופקית, ערכי האריחים בתוך האריח #ba86d972 @desktop @prod-safe`, async ({ page }) => {
      await page.setViewportSize({ width: w, height: 800 });
      for (const name of ['test', 'אלינה בדיקה']) { // «test» — 2 кнопки, «אלינה בדיקה» — 3 кнопки
        if (name === 'test') await page.goto(TEST_CARD);
        else {
          await page.setViewportSize({ width: 1440, height: 900 }); // список — в десктопной раскладке
          await openList(page);
          if (!(await rowOf(page, name).count())) continue; // клиента нет на первой странице — проверяем только «test»
          await openCard(page, name);
          await page.setViewportSize({ width: w, height: 800 });
        }
        const card = { name };
        const h1 = page.getByRole('heading', { level: 1, name: card.name });
        await expect(h1).toBeVisible({ timeout: 20_000 });
        const m = await h1.evaluate((el) => {
          const r = document.createRange();
          r.selectNodeContents(el);
          const cs = getComputedStyle(el);
          return { h: el.getBoundingClientRect().height, w: el.clientWidth, textW: r.getBoundingClientRect().width, lh: parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.25, bottom: el.getBoundingClientRect().bottom };
        });
        expect(m.w, `${card.name}: имя не сжато (было 0–8px)`).toBeGreaterThanOrEqual(m.textW - 1);
        expect(m.h, `${card.name}: имя в одну строку`).toBeLessThan(m.lh * 1.6);
        const edit = (await page.getByRole('button', { name: 'עריכה' }).boundingBox())!;
        expect(edit.y, `${card.name}: кнопки ниже имени`).toBeGreaterThanOrEqual(m.bottom - 1);
        await expect(page.getByRole('heading', { level: 3, name: 'הזמנות אחרונות' })).toBeVisible();
        expect(await page.evaluate(() => document.documentElement.scrollWidth), `${card.name}: без горизонтальной прокрутки`).toBeLessThanOrEqual(w);
        for (const t of TILES) {
          const label = page.getByRole('main').getByText(t, { exact: true });
          const inside = await label.evaluate((el) => {
            const tile = el.parentElement!.getBoundingClientRect();
            const r = document.createRange();
            r.selectNodeContents(el.nextElementSibling!);
            const v = r.getBoundingClientRect();
            return { left: v.left - tile.left, right: tile.right - v.right };
          });
          expect(inside.left, `${card.name} · «${t}»: значение внутри плитки слева`).toBeGreaterThanOrEqual(8);
          expect(inside.right, `${card.name} · «${t}»: значение внутри плитки справа`).toBeGreaterThanOrEqual(8);
        }
      }
    });
  }
});
